CREATE TABLE IF NOT EXISTS quote_documents (quote_id TEXT NOT NULL REFERENCES quotes(id), ordinal INTEGER NOT NULL, fingerprint TEXT NOT NULL, original_filename TEXT NOT NULL, token_counts_json TEXT NOT NULL, needs_outline_recovery INTEGER NOT NULL CHECK(needs_outline_recovery IN(0,1)), failed INTEGER NOT NULL CHECK(failed IN(0,1)), PRIMARY KEY(quote_id, ordinal), UNIQUE(quote_id, fingerprint));
INSERT OR IGNORE INTO quote_documents(quote_id, ordinal, fingerprint, original_filename, token_counts_json, needs_outline_recovery, failed) SELECT q.id, d.key + 1, json_extract(d.value, '$.fingerprint'), json_extract(d.value, '$.originalFilename'), json(json_extract(d.value, '$.tokenCounts')), CASE WHEN json_extract(d.value, '$.needsOutlineRecovery') THEN 1 ELSE 0 END, CASE WHEN json_extract(d.value, '$.failed') THEN 1 ELSE 0 END FROM quotes q, json_each(q.request_json) d WHERE json_valid(q.request_json) AND json_type(q.request_json) = 'array' AND json_type(d.value) = 'object' AND json_extract(d.value, '$.fingerprint') IS NOT NULL;
ALTER TABLE documents ADD COLUMN ordinal INTEGER;
UPDATE documents SET ordinal = CAST(substr(tag, instr(tag, '-') + 1) AS INTEGER) WHERE ordinal IS NULL AND tag GLOB 'r*-[0-9]*';
